-- Idee inserite in blocco da Francesco il 24/11/2026: ognuna è una proposta singola, così ogni persona vota per ogni locale.
-- Nessun voto automatico. Le colonne zona e note_org sono quelle riservate a chi gestisce: note_org contiene etichette lette dall'app
-- (m = minori: si, no, pasto, ? oppure l'ora limite; ll = coordinate; min = minuti da King's Cross; z = zona della metro).
-- Se un titolo esiste già non viene duplicato.
insert into public.proposals (campaign_id, participant_id, titolo, categoria, descrizione, indirizzo, maps_url, sito_url, zona, note_org)
select c.id, p.id, v.titolo, v.categoria, v.descrizione, v.indirizzo, v.maps_url, v.sito_url, v.zona, v.note_org
from public.campaigns c
join public.participants p on p.campaign_id = c.id and lower(p.nome) = 'francesco'
cross join (values
  ($q$The Grapes, Limehouse$q$, $q$locali$q$, $q$Pub del 1720 sul Tamigi, citato da Dickens, con sala al piano di sopra sul fiume. MINORI: il sito del pub dice che i visitatori sono benvenuti ma una guida li segna come non ammessi: da chiedere (tel. 020 7987 4396). Orari 24-27/12 da verificare. Circa 31 minuti da King's Cross con i mezzi (stima).$q$, $q$76 Narrow Street, Limehouse, London E14 8BP$q$, $q$https://www.google.com/maps/search/?api=1&query=51.50885,-0.03396$q$, $q$https://thegrapes.co.uk/$q$, $q$Limehouse (zona 2)$q$, $q$m=?;ll=51.50885,-0.03396;min=31;z=2$q$),
